-- DungeonMapDB: dungeon / raid maps for the world map's dungeon view.
-- GENERATED by tools/dungeonmaps_export.py from the ClassicDungeonMaps addon's
-- tables, the bosses' levels from MUI_NpcDB - don't edit by hand.
--
-- _maps[code][floor] = { name, path, ext, pins }: twelve 256px tiles
-- <path><1..12><ext> in a 4x3 grid. Most are the client's own
-- Interface\Worldmap tiles; dungeons that were later remade ship their
-- vanilla layout in assets/textures/dungeonmaps.
-- pin = { x, y (0-1 across the map), text, angle?, size?,
--         boss = creature display id | atlas = Blizzard atlas name,
--         minLevel?, maxLevel? (a boss's; -1: a boss rank, shown "??"),
--         link = { code, floor }? (click opens that floor), exit = true? }
-- _subzones = { { code, floor, <language> = { text, ... } } }: the minimap
-- subzone texts that show a floor, without their spaces, in every language.
-- _instances[instance id] = { code, floor }: the floor an instance opens on.

object "DungeonMapDB" {
    GetFloors = function(self, code)
        return self._maps[code]
    end;

    -- code, floor for the minimap's subzone text / GetInstanceInfo's instance
    -- id; nil when unknown.
    FindBySubzone = function(self, name)
        local hit = self._bySubzone[string.gsub(name or "", "%s+", "")]
        if hit then return hit[1], hit[2] end
    end;

    FindByInstance = function(self, id)
        local hit = self._instances[id]
        if hit then return hit[1], hit[2] end
    end;

    -- The pins' text in the client's language, from MUI_DB/Locale: English
    -- text -> text.
    Localize = function(self, texts)
        for _, floors in pairs(self._maps) do
            for _, floor in pairs(floors) do
                for _, pin in ipairs(floor.pins) do
                    pin.text = texts[pin.text] or pin.text
                end
            end
        end
    end;

